nextflow_process {

    name "Test Process FOLDSEEK_EASYSEARCH"
    script "../main.nf"
    process "FOLDSEEK_EASYSEARCH"
    tag "modules"
    tag "modules_nfcore"
    tag "foldseek"
    tag "foldseek/createdb"
    tag "foldseek/easysearch"

    setup {
        run("FOLDSEEK_CREATEDB") {
            script "../../createdb/main.nf"
            process {
                """
                input[0] = [
                    [ id:'test_db' ],
                    file(params.modules_testdata_base_path + 'proteomics/pdb/1tim.pdb', checkIfExists: true)
                ]
                """
            }
        }
    }

    test("proteomics - pdb") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test_search' ],
                    file(params.modules_testdata_base_path + 'proteomics/pdb/8tim.pdb', checkIfExists: true)
                ]
                input[1] = FOLDSEEK_CREATEDB.out.db
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.aln.get(0).get(1)).readLines().contains("8tim_A\t1tim_A\t0.967\t247\t8\t0\t1\t247\t1\t247\t1.152E-43\t1526") },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys : ["aln"])).match() }
            )
        }

    }

    test("proteomics - pdb - lookup fallback") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test_search' ],
                    file(params.modules_testdata_base_path + 'proteomics/pdb/8tim.pdb', checkIfExists: true)
                ]
                input[1] = FOLDSEEK_CREATEDB.out.db.map { meta, db -> [ [ id:'other_db' ], db ] }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.aln.get(0).get(1)).readLines().contains("8tim_A\t1tim_A\t0.967\t247\t8\t0\t1\t247\t1\t247\t1.152E-43\t1526") },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys : ["aln"])).match() }
            )
        }

    }

    test("proteomics - pdb - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test_search' ],
                    file(params.modules_testdata_base_path + 'proteomics/pdb/8tim.pdb', checkIfExists: true)
                ]
                input[1] = FOLDSEEK_CREATEDB.out.db
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}

